package com.rodrigosambade.offlinefirst; import android.content.Context;import androidx.room.*;@Database(entities={NoteEntity.class},version=1,exportSchema=false) public abstract class AppDatabase extends RoomDatabase{public abstract NoteDao notes();private static volatile AppDatabase INSTANCE;public static AppDatabase get(Context c){if(INSTANCE==null) synchronized(AppDatabase.class){if(INSTANCE==null)INSTANCE=Room.databaseBuilder(c.getApplicationContext(),AppDatabase.class,"offline.db").build();}return INSTANCE;}}